"use strict";(globalThis.webpackChunkmythogen_engine_blog=globalThis.webpackChunkmythogen_engine_blog||[]).push([[7315],{9151(e,t,n){n.r(t),n.d(t,{assets:()=>h,contentTitle:()=>o,default:()=>c,frontMatter:()=>s,metadata:()=>r,toc:()=>l});var i=n(74848),a=n(28453);const s={title:"Night-Vision Goggles Under the Searchlight \u2014 What Got Left Out Between an Interview and a Summary",date:new Date("2026-08-03T00:00:00.000Z"),lang:"en",section:"sober-record",topic:"media-literacy",article_tags:{zh:["\u5a92\u9ad4\u7d20\u990a","\u77e5\u8b58\u4e2d\u4ecb","AI\u7522\u696d","\u8a8d\u77e5\u5c01\u9396"],en:["media-literacy","knowledge-brokering","ai-industry","cognitive-blockade"]},keywords:["Waki","Sega Cheng","Lin Hung-wen","curator economy","searchlight"],summary:"The brilliance and blind spots of a podcast summary: when the curation layer profits more than the excavation layer, the market produces more curators \u2014 not more excavators.",status:"published",reading_time:12,sidebar_label:"Night-Vision Goggles Under the Searchlight \u2014 What Got Left Out Between an Interview and a Summary",sidebar_position:20260803,description:"The brilliance and blind spots of a podcast summary: when the curation layer profits more than the excavation layer, the market produces more curators \u2014 not more excavators."},o="Night-Vision Goggles Under the Searchlight \u2014 What Got Left Out Between an Interview and a Summary",r={id:"TechNotes/\u63a2\u7167\u71c8\u4e0b\u9762\u7684\u591c\u8996\u93e1\u2014\u2014\u4e00\u5834\u8a2a\u554f\u8207\u4e00\u7bc7\u6574\u7406\u4e4b\u9593\uff0c\u88ab\u7701\u7565\u6389\u7684\u6771\u897f",title:"Night-Vision Goggles Under the Searchlight \u2014 What Got Left Out Between an Interview and a Summary",description:"The brilliance and blind spots of a podcast summary: when the curation layer profits more than the excavation layer, the market produces more curators \u2014 not more excavators.",source:"@site/i18n/en/docusaurus-plugin-content-docs/current/TechNotes/\u63a2\u7167\u71c8\u4e0b\u9762\u7684\u591c\u8996\u93e1\u2014\u2014\u4e00\u5834\u8a2a\u554f\u8207\u4e00\u7bc7\u6574\u7406\u4e4b\u9593\uff0c\u88ab\u7701\u7565\u6389\u7684\u6771\u897f.md",sourceDirName:"TechNotes",slug:"/TechNotes/\u63a2\u7167\u71c8\u4e0b\u9762\u7684\u591c\u8996\u93e1\u2014\u2014\u4e00\u5834\u8a2a\u554f\u8207\u4e00\u7bc7\u6574\u7406\u4e4b\u9593\uff0c\u88ab\u7701\u7565\u6389\u7684\u6771\u897f",permalink:"/en/docs/TechNotes/\u63a2\u7167\u71c8\u4e0b\u9762\u7684\u591c\u8996\u93e1\u2014\u2014\u4e00\u5834\u8a2a\u554f\u8207\u4e00\u7bc7\u6574\u7406\u4e4b\u9593\uff0c\u88ab\u7701\u7565\u6389\u7684\u6771\u897f",draft:!1,unlisted:!1,tags:[],version:"current",sidebarPosition:20260803,frontMatter:{title:"Night-Vision Goggles Under the Searchlight \u2014 What Got Left Out Between an Interview and a Summary",date:"2026-08-03T00:00:00.000Z",lang:"en",section:"sober-record",topic:"media-literacy",article_tags:{zh:["\u5a92\u9ad4\u7d20\u990a","\u77e5\u8b58\u4e2d\u4ecb","AI\u7522\u696d","\u8a8d\u77e5\u5c01\u9396"],en:["media-literacy","knowledge-brokering","ai-industry","cognitive-blockade"]},keywords:["Waki","Sega Cheng","Lin Hung-wen","curator economy","searchlight"],summary:"The brilliance and blind spots of a podcast summary: when the curation layer profits more than the excavation layer, the market produces more curators \u2014 not more excavators.",status:"published",reading_time:12,sidebar_label:"Night-Vision Goggles Under the Searchlight \u2014 What Got Left Out Between an Interview and a Summary",sidebar_position:20260803,description:"The brilliance and blind spots of a podcast summary: when the curation layer profits more than the excavation layer, the market produces more curators \u2014 not more excavators."},sidebar:"docs",previous:{title:"When AI Undergoes Qualitative Change, Why Is Everyone Still Talking About Quantity?",permalink:"/en/docs/TechNotes/\u7576 AI \u7522\u751f\u8cea\u8b8a\uff0c\u70ba\u4ec0\u9ebc\u5927\u5bb6\u9084\u5728\u8a0e\u8ad6\u91cf\uff1f"},next:{title:"Two Kinds of Judgment: The True Difficulty of AI Collaborative Writing\u2014Starting from a Novel and a History of Technology",permalink:"/en/docs/TechNotes/AI \u5354\u4f5c\u5beb\u4f5c\u7684\u771f\u6b63\u96e3\u5ea6\u2014\u2014\u5f9e\u4e00\u672c\u5c0f\u8aaa\u548c\u4e00\u672c\u79d1\u6280\u53f2\u8aaa\u8d77"}},h={},l=[{value:"I. Whose Searchlight Is It?",id:"i-whose-searchlight-is-it",level:2},{value:"II. The 8% Gateway, and the 92% Who Never Walk Through",id:"ii-the-8-gateway-and-the-92-who-never-walk-through",level:2},{value:"III. The Invisible Boundaries of the Dialogue",id:"iii-the-invisible-boundaries-of-the-dialogue",level:2},{value:"IV. The Other Half of &quot;AI Can&#39;t Write Facts&quot;",id:"iv-the-other-half-of-ai-cant-write-facts",level:2},{value:"V. Japan&#39;s Slowness, and the Blocked Road",id:"v-japans-slowness-and-the-blocked-road",level:2},{value:"VI. The Exchange Rate of Trust",id:"vi-the-exchange-rate-of-trust",level:2},{value:"VII. What This Article Cannot Do",id:"vii-what-this-article-cannot-do",level:2}];function d(e){const t={em:"em",h1:"h1",h2:"h2",header:"header",hr:"hr",img:"img",p:"p",strong:"strong",...(0,a.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"night-vision-goggles-under-the-searchlight--what-got-left-out-between-an-interview-and-a-summary",children:"Night-Vision Goggles Under the Searchlight \u2014 What Got Left Out Between an Interview and a Summary"})}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.img,{src:"https://imagedelivery.net/kDRCweMmqLnTPNlbum-pYA/prod/embed/2a61a7cb-367d-4d11-94cb-1a0b16b1c2cf.png/public",alt:""})}),"\n",(0,i.jsxs)(t.p,{children:["Toward the end of July, Waki of the Reading Outpost published a long-form piece summarising an episode of Sega Cheng's podcast ",(0,i.jsx)(t.em,{children:"Sega on AI"}),". The guest was veteran tech journalist Lin Hung-wen, author of ",(0,i.jsx)(t.em,{children:"Light on the Chip Island"}),"."]}),"\n",(0,i.jsx)(t.p,{children:"The article is well written. Sharp imagery, compelling data, a resonant ending. If all you want is a three-minute overview of what the episode covered, this summary is top-tier work."}),"\n",(0,i.jsx)(t.p,{children:"But when I finished reading, what lit up in my mind was not the searchlight inside the article \u2014 it was everything the searchlight failed to reach. What follows is not a critique \u2014 what Waki does has its own value \u2014 but a pair of night-vision goggles: view the same landscape under a different spectrum, and you will see what vanished in the white light."}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"i-whose-searchlight-is-it",children:"I. Whose Searchlight Is It?"}),"\n",(0,i.jsx)(t.p,{children:"Waki deployed a powerful image: the semiconductor boom is like an enormous searchlight \u2014 illuminating TSMC, illuminating share prices, illuminating GDP \u2014 but what truly sustains a place is groundwater and soil."}),"\n",(0,i.jsx)(t.p,{children:"The metaphor draws its power from intuition. But it skips a premise: a searchlight is not a natural phenomenon. Someone holds it. Someone decides where it points."}),"\n",(0,i.jsx)(t.p,{children:"Waki's approach is: \"If the searchlight doesn't reach you, go dig a well.\" This is advice on the level of individual choice \u2014 pleasant to hear, and not wrong. But it sidesteps a sharper question: is the searchlight aimed precisely to ensure you cannot see what lies at the bottom of the well?"}),"\n",(0,i.jsx)(t.p,{children:"Lin Hung-wen's data already touches this layer: Taiwan's wage share of GDP has fallen from 49.3% to 43.89% over forty years; TSMC's median salary is 5.5 times the national figure, and the gap is accelerating. Waki cited these numbers and concluded: \"a sense of deprivation.\""}),"\n",(0,i.jsx)(t.p,{children:"But the numbers can be pushed further. A persistently declining wage share means the portion of value created by enterprises that goes to labour shrinks every year. This is not natural market divergence \u2014 when you place it alongside the financial statements of the global tech industry, the same pattern repeats: record revenues accompanied by simultaneous layoffs; the saved wages become capital expenditure and stock buybacks; buybacks inflate earnings per share, inflate stock prices, inflate executive compensation. The brighter the searchlight, the lower the water table \u2014 not a coincidence, but the same pipeline at work."}),"\n",(0,i.jsx)(t.p,{children:"Waki did not go this deep. Not because he cannot see it, but because going this deep would make the article something that can no longer be digested in three minutes. And three-minute digestibility is precisely his product specification."}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"ii-the-8-gateway-and-the-92-who-never-walk-through",children:"II. The 8% Gateway, and the 92% Who Never Walk Through"}),"\n",(0,i.jsx)(t.p,{children:"One thing must be stated clearly first: Waki has never claimed to be a substitute for the original book."}),"\n",(0,i.jsx)(t.p,{children:"He has said many times across his own content that what he produces is roughly an 8% to 15% distillation of a book's essence. And his intention is not to keep you at that 8% \u2014 quite the opposite. What he does is guided discovery: helping you judge whether a book is worth your time, then nudging you to go find and read it. The design logic of the Reading Outpost is a gateway, not a replacement. Waki is honest about this positioning, and in practice he consistently pushes in that direction."}),"\n",(0,i.jsx)(t.p,{children:"But can he actually push hard enough?"}),"\n",(0,i.jsx)(t.p,{children:"There is a force beyond his control pushing back. Waki opens the door and points inside, saying \"it's worth going in.\" But the moment the reader stands at the threshold, the algorithm is already serving up the next summary, the next book digest, the next three-minute cheat sheet. The platform's commercial logic is to retain attention, not to send it away \u2014 every reader who leaves the page to buy a book is, from the platform's perspective, a loss. Waki pushes you to walk through; the algorithm pushes you to swipe sideways."}),"\n",(0,i.jsx)(t.p,{children:'The result: 8% is enough. Enough to form an impression, enough to make dinner-table conversation, enough to forward to a friend with "this is an interesting take," enough to feel you "know" it. This is not Waki\'s design intent \u2014 he wants you to read the entire book. But in an ecosystem where attention is perpetually siphoned, the better the gateway is built, the more people feel satisfied at the gateway. It is not the intermediary blocking the path \u2014 it is the ecosystem intercepting the people on the path.'}),"\n",(0,i.jsx)(t.p,{children:'Lin Hung-wen spent thirty years covering news and accumulated the kind of judgment that concludes: "the real reason the acquisition fell through is that a particular shareholder didn\'t want to sell." The production cost of this judgment is extraordinarily high \u2014 you need to attend thousands of press conferences, sit through hundreds of meals, lose trust a few times, endure several rounds of litigation risk. Waki takes one facet of that judgment and converts it, in three minutes, into a consumable knowledge product, then tells you: go read the original. The facet is accurate, the recommendation sincere. But how many actually walk through?'}),"\n",(0,i.jsx)(t.p,{children:"Now look at the market's structure. Lin Hung-wen himself mentioned in the interview that when he entered the profession thirty-three years ago, the starting monthly salary was NT$38,000. Today, new entrants start at just over NT$30,000. Thirty years, and the number has not moved forward. Over the same period, the business model of knowledge intermediation \u2014 from book digests and reading clubs to podcast summaries \u2014 went from nonexistent to an industry."}),"\n",(0,i.jsx)(t.p,{children:'This is not because intermediaries stole the excavators\' lunch. What intermediaries do \u2014 guided discovery, filtering, reducing the cost of choice \u2014 has genuine value. But the market\'s attention is finite: when most readers obtain "enough understanding" at the gateway and stop walking forward, the economic foundation of the excavation layer will continue to shrink \u2014 not stolen, but bypassed. Journalist salaries don\'t rise not because someone is suppressing them, but because the entire ecosystem has made "enough" too easy to obtain.'}),"\n",(0,i.jsx)(t.p,{children:'"What AI does is curation, not excavation" \u2014 the weight of Lin Hung-wen\'s statement shifts under this structural lens. Because before AI appeared, the human curation industry was already doing the same thing. AI did not invent this model; AI compressed the production cost of 8% to near zero, making "enough understanding" cheaper, faster, and more ubiquitous \u2014 while the cost of excavation \u2014 thirty years, thousands of press conferences, hundreds of meals \u2014 has not dropped by a single cent. Waki nudges you to read the original; AI doesn\'t even bother nudging, it feeds the 8% straight to your lips.'}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"iii-the-invisible-boundaries-of-the-dialogue",children:"III. The Invisible Boundaries of the Dialogue"}),"\n",(0,i.jsx)(t.p,{children:"Step back one more level and look at the structure of the dialogue itself."}),"\n",(0,i.jsxs)(t.p,{children:["Sega Cheng is the founder of iKala \u2014 a company in AI and digital marketing. His podcast is called ",(0,i.jsx)(t.em,{children:"Sega on AI"}),'. He invited Lin Hung-wen for a conversation about "who is pocketing Taiwan\'s AI money."']}),"\n",(0,i.jsx)(t.p,{children:"Notice the structure: an AI company founder invites a veteran journalist onto his own content-marketing channel to discuss where the AI industry's money is flowing."}),"\n",(0,i.jsx)(t.p,{children:'No one needs to harbour ill intent. But a space that operates under the banner of "exchange" with commerce as its foundation will naturally filter for voices that are harmless to its commercial interests. Every statement Lin Hung-wen made in the conversation \u2014 "the bubble is still far off," "AI can\'t write facts," "Japan\'s craftsman spirit is worth learning from" \u2014 is entirely harmless to iKala\'s commercial interests. "The bubble is still far off" means AI investment should continue; "AI can\'t write facts" means AI has boundaries but remains valuable; "learn Japan\'s slowness" means patience and long-term commitment are needed \u2014 and long-term commitment requires more AI tools and services.'}),"\n",(0,i.jsx)(t.p,{children:"What would genuinely uncomfortable questions look like in this space?"}),"\n",(0,i.jsx)(t.p,{children:'"Layoffs and record profits appear on the same earnings report \u2014 where did the saved wages go?"'}),"\n",(0,i.jsx)(t.p,{children:"\"Has the term 'AI transformation,' in the language of financial reporting, already shifted from a technical description to a licence for layoffs?\""}),"\n",(0,i.jsx)(t.p,{children:'"In Taiwan\'s AI education-subsidy ecosystem, how much public money ultimately flows into the anxiety-monetisation course market?"'}),"\n",(0,i.jsxs)(t.p,{children:["These questions will not appear on ",(0,i.jsx)(t.em,{children:"Sega on AI"}),'. Not because Sega Cheng deliberately avoids them \u2014 he may not have even thought to ask \u2014 but because the space itself has an invisible boundary: what questions are "appropriate" to discuss here and what questions are "inappropriate" is understood by all without being stated.']}),"\n",(0,i.jsx)(t.p,{children:"Waki's summary faithfully reflects this boundary. What he can curate is limited to what was said within the space. The silence outside the space is not in his source material."}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"iv-the-other-half-of-ai-cant-write-facts",children:'IV. The Other Half of "AI Can\'t Write Facts"'}),"\n",(0,i.jsx)(t.p,{children:'Lin Hung-wen made a statement that Waki framed and highlighted: "AI cannot write human bias." His point was that the source of bias is human; AI is merely the pen.'}),"\n",(0,i.jsx)(t.p,{children:"The first half of this statement is correct. The second half needs correction."}),"\n",(0,i.jsx)(t.p,{children:'AI does not generate original bias. But AI perfectly replicates and amplifies existing bias \u2014 and it does so better than anyone, because its amplification is silent, scalable, and borderless. If an AI learns from its training corpus that the association between "Nintendo" and "platform lock-in" is weak, it will not proactively search for the 10NES lockout chip that Nintendo embedded in NES cartridges in 1985 \u2014 the result is that AI-generated analyses of the gaming industry will systematically omit a critical fact, and readers will not know it was omitted.'}),"\n",(0,i.jsx)(t.p,{children:"Even more dangerous is AI hallucination \u2014 not random nonsense, but a confident delivery of a judgment that is structurally complete, logically coherent, fully assembled, yet directionally wrong. Its errors don't look like errors; they look like an argument you almost agree with."}),"\n",(0,i.jsx)(t.p,{children:"The acquisition example Lin Hung-wen gave \u2014 \"the real reason was that a particular shareholder didn't want to sell, but this was never written down anywhere\" \u2014 is precisely the kind of thing AI can never do. But when Waki cited this statement, he did something subtle: he compressed thirty years of a journalist's accumulated judgment into a shareable soundbite. The soundbite circulated; the judgment did not."}),"\n",(0,i.jsx)(t.p,{children:"Readers finish Waki's article and remember the seven characters: \"AI can't write facts.\" But they will not thereby learn how to discern what is missing from an AI-generated industry analysis \u2014 because that ability is not in the soundbite; it is in thirty years of field experience."}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"v-japans-slowness-and-the-blocked-road",children:"V. Japan's Slowness, and the Blocked Road"}),"\n",(0,i.jsx)(t.p,{children:"Both Waki and Lin Hung-wen praised Japan's slowness. Kao pivoted from washing faces to cleaning wafers; Shin-Etsu went from fertiliser to the world's largest wafer supplier \u2014 decades of deep cultivation in exchange for a moat that cannot be replicated by short-termism."}),"\n",(0,i.jsx)(t.p,{children:'The observation is accurate. But it stops at a comfortable place: "We should learn from Japan and go deeper on one thing."'}),"\n",(0,i.jsx)(t.p,{children:"The question is: why isn't anyone learning?"}),"\n",(0,i.jsx)(t.p,{children:'The answer is not the cultural explanation of "Taiwanese people are too impatient." The answer lies in structure.'}),"\n",(0,i.jsxs)(t.p,{children:['More precisely, what is truly worth learning from Japan may not be "slowness," but rather that ',(0,i.jsx)(t.strong,{children:"between narrative and production, they chose to produce"}),'. Japan\'s strength has never been about developing slowly; it is about the willingness to spend decades genuinely building industries, technologies, quality, and supply chains. The so-called "slowness" is merely the natural timescale that emerges from building something real.']}),"\n",(0,i.jsx)(t.p,{children:"Take the gaming industry as an example. Sega's RGG Studio: seventy people, twenty years, more than fifteen titles \u2014 consistent reputation, consistent quality, consistent sales. This is precisely the kind of Japanese-style deep cultivation that Lin Hung-wen and Waki praised: not chasing short-term valuations and narratives, but making genuinely good products over the long term."}),"\n",(0,i.jsx)(t.p,{children:"During the same period, Sony spent $400 million developing Concord. Peak concurrent players on Steam: 697. Permanently delisted two weeks after launch."}),"\n",(0,i.jsx)(t.p,{children:'What is unaffordable is not the game. What is unaffordable is acquisition premiums, management bloat, and the self-replication of administrative structures. After costs are inflated to astronomical levels, the inflated figures become "industry standards" \u2014 and then everyone says "AAA games are too expensive; it\'s unsustainable." The narrative manufactures scarcity; scarcity justifies the necessity of monopoly.'}),"\n",(0,i.jsxs)(t.p,{children:["This is precisely the difference between narrative and production: ",(0,i.jsx)(t.strong,{children:"narrative can rapidly manufacture valuations, stories, and imagination; production demands time, cost, and genuine capability accumulation."}),' When a market begins to reward "telling stories" more than "making things," capital will naturally flow to the former, while those who actually build real businesses find it increasingly difficult to survive.']}),"\n",(0,i.jsx)(t.p,{children:'"Learn from Japan" is not about unwillingness \u2014 it is about a blocked road. What blocks it is not cultural DNA but capital structure: when financial returns persistently exceed productive returns, capital will not flow to those who make things. You can encourage a young person to "dig a well," but if someone has built a car park over the wellhead, encouragement is nothing more than a nice-sounding phrase.'}),"\n",(0,i.jsxs)(t.p,{children:["Waki's article stops at encouragement. The night-vision goggles see the car park; and one layer deeper, they see ",(0,i.jsx)(t.strong,{children:"a society beginning to lose the ability to distinguish narrative from production."})]}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"vi-the-exchange-rate-of-trust",children:"VI. The Exchange Rate of Trust"}),"\n",(0,i.jsx)(t.p,{children:'Waki cited a data point: the appeal of AI-generated content is only one-sixth to one-seventh that of authentic content. His conclusion: "The more AI content there is, the stronger the desire for authentic content will become, and the higher the price people are willing to pay."'}),"\n",(0,i.jsx)(t.p,{children:"He then cited Gartner's estimate: by 2030, global enterprises will spend over $25 billion annually to confirm a single thing \u2014 \"whether it's real.\""}),"\n",(0,i.jsx)(t.p,{children:"Put these two data points together and they look like good news \u2014 authentic content has value, and that value is rising."}),"\n",(0,i.jsx)(t.p,{children:"But think one layer further: who can afford to pay for that value?"}),"\n",(0,i.jsx)(t.p,{children:"The $25 billion fact-verification market has enterprises as buyers. Investment institutions with budgets for due diligence, multinational corporations with legal departments, government agencies with intelligence needs. Ordinary readers are not in this market."}),"\n",(0,i.jsx)(t.p,{children:'And so the exchange rate of trust forks: the wealthy purchase verified facts to make decisions; ordinary people consume free curated content to form impressions. The gap between the two is not a gap in "reading volume" \u2014 it is a gap in "decision quality." And the gap in decision quality ultimately becomes a gap in wealth.'}),"\n",(0,i.jsxs)(t.p,{children:["Who buys Lin Hung-wen's judgment? Those who can afford to read ",(0,i.jsx)(t.em,{children:"Light on the Chip Island"}),", those who have access to this calibre of in-depth conversation. Who buys Waki's summaries? Those who don't have time to listen to the full podcast episode. What the two layers of readers receive appears on the surface to be the same story; in reality, it is two world-images of entirely different resolution."]}),"\n",(0,i.jsx)(t.p,{children:"And this resolution gap \u2014 AI will not narrow it; AI will only widen it. Because what AI excels at is precisely the mass production of low-resolution, high-circulation curated content \u2014 compressing complexity into soundbites, compressing contradictions into conclusions, compressing things that demand pause and thought into things you can swipe past."}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"vii-what-this-article-cannot-do",children:"VII. What This Article Cannot Do"}),"\n",(0,i.jsx)(t.p,{children:'Waki\'s article ends by asking the reader: "Are you digging a well, or chasing the light?"'}),"\n",(0,i.jsx)(t.p,{children:"I don't ask."}),"\n",(0,i.jsx)(t.p,{children:'Not because the answer doesn\'t matter, but because the act of asking is itself a packaging \u2014 demoting a structural problem to an individual choice. "Are you digging a well?" implies the problem lies with you. But if a car park has been built over the wellhead, whether you dig is one matter; why the car park is there is another.'}),"\n",(0,i.jsx)(t.p,{children:'What this article can do is hand you the lens of the night-vision goggles. Put them on and re-read Waki\'s piece \u2014 see who holds the searchlight, the exchange rate between curators and excavators, the invisible boundaries of the dialogue space, the soundbite that circulated while judgment did not, what blocked the road to "learning from Japan."'}),"\n",(0,i.jsx)(t.p,{children:"What this article cannot do is dig that well for you. Because the well's location is in your own experience, not in any article \u2014 including this one."}),"\n",(0,i.jsx)(t.p,{children:"But one thing is certain: if you finish this article and then go back to Waki's, you will see something different."}),"\n",(0,i.jsx)(t.p,{children:"And seeing something different is the entire purpose of the night-vision goggles."})]})}function c(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},28453(e,t,n){n.d(t,{R:()=>o,x:()=>r});var i=n(96540);const a={},s=i.createContext(a);function o(e){const t=i.useContext(s);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:o(e.components),i.createElement(s.Provider,{value:t},e.children)}}}]);